    for (super_id, subs) in ranges
        isempty(subs) && continue
        local row_entries = NamedTuple{(:index, :value),Tuple{Int,Tuple{Int,Int}}}[]
        for (range, substitution_index) in subs
            for class_id in range.start:range.end_
