    push!(self._functions_containing_parameters, Base.IdSet{UnionAll}())
    self._function_for_parameter[node.var] = slot
    # super.visitFunctionType(node): the parameter's bounds, then the body, each type's parts in turn;
    # a parameter that is a value (`1` in `NTuple{1,T}`) has none
    local pending = Union{Type,TypeVar,Core.TypeofVararg}[node.body, node.var.ub, node.var.lb]
    while !isempty(pending)
        local t = pop!(pending)
        if t isa UnionAll
            visit_function_type(self, t)
        elseif t isa TypeVar
            # a parameter the walk's binders bind is dart's StructuralParameterType; any other is a
            # class or method parameter, dart's TypeParameterType, which the walk passes by
            haskey(self._function_for_parameter, t) && visit_structural_parameter_type(self, t)
        elseif t isa Union
            push!(pending, t.b, t.a)
        elseif t isa DataType
            for p in Iterators.reverse(t.parameters)
                p isa Union{Type,TypeVar,Core.TypeofVararg} && push!(pending, p)
            end
        elseif t isa Core.TypeofVararg
            isdefined(t, :N) && t.N isa TypeVar && push!(pending, t.N)
            isdefined(t, :T) && push!(pending, t.T)
        end
