    for inner in self._functions_containing_parameters[end]
        # a UnionAll binds one parameter
        offset = max(offset, self.types.function_type_parameter_offset[inner] + 1)
    end
    self.types.function_type_parameter_offset[node] = offset
    self.types.function_type_parameter_index[node.var] = offset
    pop!(self._functions_containing_parameters)
    pop!(self._function_stack)
    return nothing
end

# a slot is dart's index into the stack, from 0; Julia's vectors count from 1
@parity "dart2wasm/lib/types.dart:1526 _FunctionTypeParameterOffsetCollector.visitStructuralParameterType" function visit_structural_parameter_type(self::_FunctionTypeParameterOffsetCollector, node::TypeVar)::Nothing
    local slot = self._function_for_parameter[node]
    for inner in slot+1:length(self._function_stack)-1
        push!(self._functions_containing_parameters[slot + 1], self._function_stack[inner + 1])
    end
    return nothing
end

